    xs = sorted(float(x) for x in values)
    n = len(xs)
    if k <= 0:
        return xs[0]
    if k >= 1:
        return xs[-1]
    # position in 1..n
    pos = (n - 1) * k + 1
    lo = int(pos)  # floor
    hi = lo if pos == lo else lo + 1
    # convert to 0-based indices
    lo_i = lo - 1
    hi_i = hi - 1
    if lo_i == hi_i:
        return xs[lo_i]
    frac = pos - lo
    return xs[lo_i] + frac * (xs[hi_i] - xs[lo_i])


